window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8c82af19a5fa1d44"]={"versions": [{"id": "FIG-8c82af19a5fa1d44", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Schichtenarchitekturdiagramm (Layered View). Links wird die standardmäßige Gesamtarchitektur des AUTOSAR Classic Platform Schichtenmodells dargestellt (Application Layer, Runtime Environment, System Services, Memory Services, Crypto Services, Communication Services, Hardware Abstraction Layers, Microcontroller Drivers, Microcontroller). Rechts wird der Krypto-Stack im Detail herausgezoomt dargestellt, unterteilt in Services, Crypto Hardware Abstraction, Crypto Drivers, Communication Drivers und Hardware-Elemente des Mikrocontrollers (μC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Architektur umfasst folgende Hauptentitäten:</p>\n<ul class=\"fig-list\"><li><strong>Crypto Services Layer</strong>: Beinhaltet den <em>Crypto Service Manager</em> (CSM).\n</li><li><strong>Crypto Hardware Abstraction Layer</strong>: Enthält das <em>Crypto Interface</em> (CryIf) sowie zugewiesene Treibereinheiten: <em>External Crypto Driver</em> und <em>Crypto Driver (SW-based)</em>.\n</li><li><strong>Crypto Drivers Layer</strong>: Umfasst interne Hardware-Treiber (<em>Crypto Driver</em>).\n</li><li><strong>Communication Drivers Layer</strong>: Enthält den <em>SPIHandlerDriver</em>.\n</li><li><strong>Microcontroller (μC) / Hardware</strong>: Beinhaltet hardwarebasierte Sicherheitsmodule wie <em>SHE</em> (Secure Hardware Extension), <em>HSM</em> (Hardware Security Module) sowie periphere Schnittstellen wie <em>SPI</em>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungen: Der <em>External Crypto Driver</em> verbindet sich über eine gerichtete Verbindungslinie mit dem <em>SPIHandlerDriver</em> in den Communication Drivers, um auf externe Kryptobausteine zuzugreifen. Die internen <em>Crypto Driver</em> binden direkt an Hardwaremodule wie SHE oder HSM an. Der <em>Crypto Driver (SW-based)</em> führt kryptografische Algorithmen rein softwarebasiert auf dem Hauptprozessor aus. Das <em>Crypto Interface</em> abstrahiert übergeordnete Anfragen für alle darunterliegenden Treiber.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Block- und Schichtenstruktur ohne Sequenzabläufe oder Protokollschritte. Der Kontroll- und Datenfluss verläuft hierarchisch von der Anwendung bzw. BSW-Modulen über die RTE an den Crypto Service Manager, weiter über das Crypto Interface an den jeweiligen Treiber (SW-basiert, interner HW-Treiber oder über SPI angebundener externer Treiber).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normative Übersicht zur Verortung des Crypto Interface (CryIf) innerhalb der AUTOSAR-Architektur. CryIf fungiert als zentrale Vermittlungs- und Abstraktionsschicht zwischen dem herstellerunabhängigen Crypto Service Manager (CSM) und den diversen kryptografischen Treiberimplementierungen (Hardware-basiert intern/extern sowie Software-basiert). Externe kryptografische Treiber greifen nicht direkt auf Hardware zu, sondern müssen über den standardisierten SPI-Treiberstack (SPIHandlerDriver) geführt werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5fb784712465f94f", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Schichtenarchitekturdiagramm (Layered View). Links wird die standardmäßige Gesamtarchitektur des AUTOSAR Classic Platform Schichtenmodells dargestellt (Application Layer, Runtime Environment, System Services, Memory Services, Crypto Services, Communication Services, Hardware Abstraction Layers, Microcontroller Drivers, Microcontroller). Rechts wird der Krypto-Stack im Detail herausgezoomt dargestellt, unterteilt in Services, Crypto Hardware Abstraction, Crypto Drivers, Communication Drivers und Hardware-Elemente des Mikrocontrollers (μC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Architektur umfasst folgende Hauptentitäten:</p>\n<ul class=\"fig-list\"><li><strong>Crypto Services Layer</strong>: Beinhaltet den <em>Crypto Service Manager</em> (CSM).\n</li><li><strong>Crypto Hardware Abstraction Layer</strong>: Enthält das <em>Crypto Interface</em> (CryIf) sowie zugewiesene Treibereinheiten: <em>External Crypto Driver</em> und <em>Crypto Driver (SW-based)</em>.\n</li><li><strong>Crypto Drivers Layer</strong>: Umfasst interne Hardware-Treiber (<em>Crypto Driver</em>).\n</li><li><strong>Communication Drivers Layer</strong>: Enthält den <em>SPIHandlerDriver</em>.\n</li><li><strong>Microcontroller (μC) / Hardware</strong>: Beinhaltet hardwarebasierte Sicherheitsmodule wie <em>SHE</em> (Secure Hardware Extension), <em>HSM</em> (Hardware Security Module) sowie periphere Schnittstellen wie <em>SPI</em>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungen: Der <em>External Crypto Driver</em> verbindet sich über eine gerichtete Verbindungslinie mit dem <em>SPIHandlerDriver</em> in den Communication Drivers, um auf externe Kryptobausteine zuzugreifen. Die internen <em>Crypto Driver</em> binden direkt an Hardwaremodule wie SHE oder HSM an. Der <em>Crypto Driver (SW-based)</em> führt kryptografische Algorithmen rein softwarebasiert auf dem Hauptprozessor aus. Das <em>Crypto Interface</em> abstrahiert übergeordnete Anfragen für alle darunterliegenden Treiber.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Block- und Schichtenstruktur ohne Sequenzabläufe oder Protokollschritte. Der Kontroll- und Datenfluss verläuft hierarchisch von der Anwendung bzw. BSW-Modulen über die RTE an den Crypto Service Manager, weiter über das Crypto Interface an den jeweiligen Treiber (SW-basiert, interner HW-Treiber oder über SPI angebundener externer Treiber).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normative Übersicht zur Verortung des Crypto Interface (CryIf) innerhalb der AUTOSAR-Architektur. CryIf fungiert als zentrale Vermittlungs- und Abstraktionsschicht zwischen dem herstellerunabhängigen Crypto Service Manager (CSM) und den diversen kryptografischen Treiberimplementierungen (Hardware-basiert intern/extern sowie Software-basiert). Externe kryptografische Treiber greifen nicht direkt auf Hardware zu, sondern müssen über den standardisierten SPI-Treiberstack (SPIHandlerDriver) geführt werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8c82af19a5fa1d44", "to": "FIG-5fb784712465f94f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
